40	// once base64-encoded), MaxBytes has to come down.
41	const (
42		MaxFiles = 500
43		MaxBytes = 32 << 20
44	)
45	
46	// Fetch returns the files of the template at src, or an error saying why it
47	// cannot be used — including that it is larger than a template may be.
48	func Fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
49		files, err := fetch(ctx, src, creds)
50		if err != nil {
51			return nil, err
52		}
53		if err := checkLimits(files); err != nil {
54			return nil, err
55		}
56		return files, nil
57	}
58	
59	// checkLimits refuses a template past MaxFiles or MaxBytes, naming the biggest
60	// file so the reader knows where to look. It runs before anything is created on
61	// the forge: a refusal after the repository exists would leave an empty one.
62	func checkLimits(files []File) error {
63		if len(files) > MaxFiles {
64			return fmt.Errorf("the template has %d files, more than the %d a template may have", len(files), MaxFiles)
65		}
66	
67		total, biggest := 0, File{}
68		for _, f := range files {
69			total += len(f.Content)
70			if len(f.Content) > len(biggest.Content) {
71				biggest = f
72			}
73		}
74		if total > MaxBytes {
75			return fmt.Errorf("the template is %s, more than the %s a template may be — the largest file is %s (%s)",
76				FormatSize(total), FormatSize(MaxBytes), biggest.Path, FormatSize(len(biggest.Content)))
77		}
78		return nil
79	}
80	
81	// FormatSize writes a byte count the way the application says it: 1.5 MiB.
82	func FormatSize(n int) string {
83		switch {
84		case n >= 1<<20:
85			return fmt.Sprintf("%.1f MiB", float64(n)/(1<<20))
86		case n >= 1<<10:
87			return fmt.Sprintf("%.1f KiB", float64(n)/(1<<10))
88		default:
89			return fmt.Sprintf("%d B", n)
90		}
91	}
92	
93	func fetch(ctx context.Context, src Source, creds Credentials) ([]File, error) {
94		if err := src.Validate(); err != nil {
95			return nil, err
96		}
97	
98		switch src.Kind {
99		case KindGit:
100			raw, err := git.ArchiveRemote(ctx, src.URL, src.Ref, src.Path, creds.Token, archiveCap)
101			if err != nil {
102				return nil, tooLargeOr(fmt.Errorf("fetching %s: %w", src.URL, err), err)
103			}
104			return readArchive(raw)
105	
106		case KindLocal:
107			raw, err := git.ArchiveLocal(ctx, src.Path, src.Ref, "", archiveCap)
108			if err != nil {
109				return nil, tooLargeOr(err, err)
110			}
111			return readArchive(raw)
112	
113		default: // KindOCI, Validate has refused anything else
114			return fetchOCI(ctx, src, creds)
115		}
116	}
117	
118	// archiveCap bounds a tar stream from git: the content a template may hold plus
119	// a header and padding per file, so a template at the limits still fits.

