1	// Package template is the catalog of repository templates: what a template is,
2	// where it lives, and how its files are fetched.
3	//
4	// A catalog entry is a reference, not a copy. The content stays where it is —
5	// a git repository, a local checkout, an OCI artifact — and is fetched when a
6	// repository is created from it, so it cannot drift from its original.
7	package template
8	
9	import (
10		"fmt"
11		"net/url"
12		"regexp"
13		"strings"
14	)
15	
16	// Kind says where a template's content lives.
17	type Kind string
18	
19	const (
20		KindGit   Kind = "git"   // a remote git repository
21		KindLocal Kind = "local" // a git repository on this machine
22		KindOCI   Kind = "oci"   // an artifact in an OCI registry
23	)
24	
25	// Kinds is every kind, in the order a form cycles through them.
26	var Kinds = []Kind{KindGit, KindLocal, KindOCI}
27	
28	// Source is the address of a template's content.
29	//
30	// The fields mean something different per kind, which is why they are named for
31	// what they hold rather than for each kind:
32	//
33	//	git    URL = clone URL, Path = optional subdirectory, Ref = branch, tag or SHA
34	//	local  Path = repository directory,                    Ref = branch, tag or SHA
35	//	oci    URL = registry URL, Path = repository,         Ref = tag
36	type Source struct {
37		Kind Kind   `yaml:"kind"`
38		URL  string `yaml:"url,omitempty"`
39		Path string `yaml:"path,omitempty"`
40		Ref  string `yaml:"ref,omitempty"`
41	}
42	
43	// Entry is one template in the catalog.
44	type Entry struct {
45		// Slug is the identifier: what a repository-creation form keeps to remember
46		// the choice, unique within the catalog.
47		Slug        string   `yaml:"slug"`
48		Name        string   `yaml:"name"`
49		Description string   `yaml:"description,omitempty"`
50		Tags        []string `yaml:"tags,omitempty"`
51		Source      Source   `yaml:"source"`
52	}
53	
54	// File is one file of a template.
55	type File struct {
56		Path       string // relative to the template root, forward slashes
57		Content    []byte
58		Executable bool
59	}
60	
61	var slugPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)
62	
63	// Validate reports why an entry cannot be stored or fetched, or nil.
64	func (e Entry) Validate() error {
65		if !slugPattern.MatchString(e.Slug) {
66			return fmt.Errorf("slug %q must be lowercase letters, digits and dashes", e.Slug)
67		}
68		if strings.TrimSpace(e.Name) == "" {
69			return fmt.Errorf("template %q has no name", e.Slug)
70		}
71		return e.Source.Validate()
72	}
73	
74	// Validate reports why a source cannot be fetched, or nil.
75	func (s Source) Validate() error {
76		switch s.Kind {
77		case KindGit:
78			if err := validateGitURL(s.URL); err != nil {
79				return err
80			}
81		case KindLocal:
82			if strings.TrimSpace(s.Path) == "" {
83				return fmt.Errorf("a local template needs a directory")
84			}
85		case KindOCI:
86			if strings.TrimSpace(s.URL) == "" || strings.TrimSpace(s.Path) == "" {
87				return fmt.Errorf("an OCI template needs a registry URL and a repository")
88			}
89			if s.Ref == "" {
90				return fmt.Errorf("an OCI template needs a tag")
91			}
92		default:
93			return fmt.Errorf("unknown source kind %q", s.Kind)
94		}
95		for _, p := range []string{s.Path, s.Ref} {
96			if strings.HasPrefix(p, "-") {
97				return fmt.Errorf("%q would be read as a command-line option", p)
98			}
99		}
100		return nil
101	}
102	
103	// validateGitURL accepts https, http, ssh and git URLs and the scp form
104	// (user@host:path), and nothing else.
105	//
106	// The catalog file can be shared, so a URL in it is not trusted: git's `ext::`
107	// transport runs a command, and `file://` reads this machine. A local checkout
108	// is a different kind (KindLocal) precisely so neither is needed here.
109	func validateGitURL(raw string) error {
110		if strings.TrimSpace(raw) == "" {
111			return fmt.Errorf("a git template needs a URL")
112		}
113		if strings.HasPrefix(raw, "-") {
114			return fmt.Errorf("%q would be read as a command-line option", raw)
115		}
116		if u, err := url.Parse(raw); err == nil && u.Scheme != "" {
117			switch u.Scheme {
118			case "https", "http", "ssh", "git":
119				if u.Host != "" {
120					return nil
121				}
122				return fmt.Errorf("%q has no host", raw)
123			}
124			return fmt.Errorf("scheme %q is not allowed for a git template", u.Scheme)
125		}
126		if scpForm.MatchString(raw) {
127			return nil
128		}
129		return fmt.Errorf("%q is not a git URL", raw)
130	}
131	
132	var scpForm = regexp.MustCompile(`^[A-Za-z0-9._-]+@[A-Za-z0-9.-]+:.+$`)
133	
134	// NormalizeTags trims, lowercases and de-duplicates tags, keeping their order
135	// and dropping empty ones. Tags are matched by the filter as typed, so they
136	// are stored the way they will be searched.
137	func NormalizeTags(tags []string) []string {
138		seen := make(map[string]bool, len(tags))
139		var out []string
140		for _, t := range tags {
141			t = strings.ToLower(strings.TrimSpace(t))
142			if t == "" || seen[t] {
143				continue
144			}
145			seen[t] = true
146			out = append(out, t)
147		}
148		return out
149	}
