88	// Compile-time proof that both can be applied to the registry: a message added
89	// without it is routed, updates the view, and leaves its row spinning for the
90	// life of the session.
91	var (
92		_ jobs.Reporter = ScanStartingMsg{}
93		_ jobs.Reporter = ScanCompleteMsg{}
94	)
95	
96	// scanJob is everything the scan needs, read in Update and carried into the
97	// Cmd, which runs on another goroutine and must not reach back into the model
98	// (Rule 110).
99	type scanJob struct {
100		entry template.Entry
101		creds template.Credentials
102		opts  scan.ScanOptions
103		run   scanFunc
104	}
105	
106	// scanTemplateCmd fetches, materializes and scans one template.
107	//
108	// contextName travels with the command rather than being read at the end (D68):
109	// the counts belong to the context the scan was launched in, whatever the user
110	// is looking at when it lands.
111	func scanTemplateCmd(job scanJob, contextName string) tea.Cmd {
112		dir, dirErr := template.ScanDir(job.entry.Slug)
113		ctx, cancel := context.WithCancel(context.Background())
114	
115		return tea.Sequence(
116			func() tea.Msg { return ScanStartingMsg{Path: dir, Cancel: cancel} },
117			func() tea.Msg {
118				defer cancel()
119				complete := ScanCompleteMsg{Slug: job.entry.Slug, Name: job.entry.Name, Path: dir}
120	
121				if dirErr != nil {
122					complete.Err = dirErr
123					return complete
124				}
125				result, err := job.scanOnce(ctx, contextName)
126				if err != nil {
127					log.Printf("ERROR [templates] scan %s: %v", job.entry.Slug, err)
128					complete.Err = err
129					return complete
130				}
131				complete.Counts = result.Counts
132				complete.Partial = len(result.Errors) > 0 && result.TotalFindings() == 0
133				return complete
134			},
135		)
136	}
137	
138	func (j scanJob) scanOnce(ctx context.Context, contextName string) (*scan.Result, error) {
139		files, err := template.Fetch(ctx, j.entry.Source, j.creds)
140		if err != nil {
141			return nil, fmt.Errorf("fetching the template: %w", err)
142		}
143		dir, err := template.Materialize(j.entry.Slug, files)
144		if err != nil {
145			return nil, fmt.Errorf("writing the template: %w", err)
146		}
147		result, err := j.run(ctx, dir, j.opts)
148		if err != nil {
149			return nil, err
150		}
151		if _, err := cache.StoreWorkspaceScan(contextName, dir, result); err != nil {
152			// The scan happened and its counts are reported; only the cache write
153			// failed, and `:sec` will not show it.
154			log.Printf("ERROR [templates] store scan %s: %v", j.entry.Slug, err)
155		}
156		return result, nil
157	}
158	
159	// scanOptions assembles the options for a template: the configured scanners,
160	// and no CI score — a template is not a repository with a pipeline to grade, and
161	// plumber would go looking for a remote it does not have.
162	func (m Model) scanOptions() scan.ScanOptions {
163		opts := scan.OptionsFromConfig(m.config)
164		opts.EnableCIScore = false
165		return opts
166	}
167	
168	// scannerState says whether a scan can run at all on this machine. Not knowing
169	// is not knowing that not: until the check comes back the key stays lit, since
170	// greying it for a few frames only to un-grey it reads as a fault (Rule 130).
171	func (m Model) scannerState() shortcut.Availability {
172		if m.deps == nil || m.deps.TrivyAvailable || m.deps.GitleaksAvailable {
173			return shortcut.Availability{}
174		}
175		return shortcut.Unavailable(reasonNoScanner)
176	}
177	
178	// scanning reports whether a scan of this directory is live, wherever it was
179	// started — the registry is one bookkeeping.
180	func (m Model) scanning(dir string) bool {
181		for _, run := range jobs.Unfinished(m.jobs) {
182			if run.Kind != jobs.KindScan {
183				continue
184			}
185			for _, item := range run.Items {
186				if item.Target == dir && !item.State.Terminal() {
187					return true
188				}
189			}
190		}
191		return false
192	}
193	
194	// startScan launches a scan of the selected template.
195	func (m Model) startScan() (tea.Model, tea.Cmd) {
196		if reason := m.refusal(m.availability().Scan); reason != "" {
197			cmd := m.footer.Warn(reason)
198			return m, cmd
199		}
200		entry, _ := m.selectedEntry()
201		dir, err := template.ScanDir(entry.Slug)
202		if err != nil {
203			log.Printf("ERROR [templates] scan directory for %s: %v", entry.Slug, err)
204			cmd := m.footer.Error("Could not scan the template — check logs")
205			return m, cmd
206		}
207	
208		job := scanJob{
209			entry: entry,
210			creds: template.CredentialsFor(m.config, m.secrets, entry.Source),
211			opts:  m.scanOptions(),
212			run:   m.scanner,
213		}
214		run := jobs.NewRun(jobs.KindScan, command.ViewTemplates, "", entry.Name, dir)
215		return m, jobs.StartInContext(run, func(contextName string) tea.Cmd {
216			return scanTemplateCmd(job, contextName)
217		})
218	}
219	
220	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
221		m.jobs = msg.Runs
222		m.footer.SetSpinnerFrame(msg.RenderedFrame)
223		return m, nil
224	}
225	
226	// handleScanComplete says how the scan ended. The counts are in the footer and
227	// the report is in `:sec`, where this directory is listed like any other scanned
228	// target.
229	func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
230		var cmd tea.Cmd
231		switch {
232		case msg.Err != nil:
233			cmd = m.footer.Error("Scan of " + msg.Name + " failed — check logs")
234		case msg.Partial:
235			cmd = m.footer.Warn("Scanned " + msg.Name + ", but a scan stage failed — check logs")
236		default:
237			cmd = m.footer.Info(scanSummary(msg))
238		}
239		return m, cmd
240	}
241	
242	// scanSummary is the one line a finished scan leaves.
243	func scanSummary(msg ScanCompleteMsg) string {
244		c := msg.Counts
245		if c.Critical+c.High+c.Medium+c.Low == 0 {
246			return "Scanned " + msg.Name + " — no findings"
247		}
248		return fmt.Sprintf("Scanned %s — %d critical, %d high, %d medium, %d low — :sec for the report",
249			msg.Name, c.Critical, c.High, c.Medium, c.Low)
250	}
251	
252	// jobsStatus is the footer's derived line while work is live.
253	func (m Model) jobsStatus() sharedcomponents.Status {
254		if text := sharedcomponents.JobsStatusLine(m.jobs, command.ViewTemplates); text != "" {
255			return sharedcomponents.Status{Text: text, Spinner: true}
256		}
257		return sharedcomponents.Status{}
258	}
